9	const cellKey = ([x, y]: Cell): string => `${x},${y}`;
10	
11	const willBeAlive = (isAlive: boolean, neighbors: number): boolean =>
12	  neighbors === 3 || (isAlive && neighbors === 2);
13	
14	export function nextGeneration(liveCells: Cell[]): Cell[] {
15	  const alive = new Set(liveCells.map(cellKey));
16	  const candidates = new Map<string, { cell: Cell; neighbors: number }>();
17	
18	  for (const [x, y] of liveCells) {
19	    for (const [dx, dy] of NEIGHBOR_OFFSETS) {
20	      const cell: Cell = [x + dx, y + dy];
21	      const k = cellKey(cell);
22	      const entry = candidates.get(k);
23	      if (entry) entry.neighbors++;
24	      else candidates.set(k, { cell, neighbors: 1 });
25	    }
26	  }
27	
28	  const next: Cell[] = [];
29	  for (const [k, { cell, neighbors }] of candidates) {
30	    if (willBeAlive(alive.has(k), neighbors)) next.push(cell);
31	  }
32	  return next;
33	}
