export function nextGeneration(liveCells: Cell[]): Cell[] {
  const alive = new Set(liveCells.map(cellKey));
  const neighborCounts = new Map<string, [Cell, number]>();

  for (const [x, y] of liveCells) {
    for (const [dx, dy] of NEIGHBOR_OFFSETS) {
      const cell: Cell = [x + dx, y + dy];
      const key = cellKey(cell);
      const [, count] = neighborCounts.get(key) ?? [cell, 0];
      neighborCounts.set(key, [cell, count + 1]);
    }
  }

  return [...neighborCounts]
    .filter(([key, [, count]]) => willBeAlive(alive.has(key), count))
    .map(([, [cell]]) => cell);
}

